import heapq
from collections import defaultdict

def find_cheapest_price(n, flights, src, dst, k):
    graph = defaultdict(list)
    for u, v, w in flights:
        graph[u].append((v, w))
    fewest = {}                        # fewest edges seen when popping each node
    heap = [(0, src, 0)]               # (cost, node, edges used)
    while heap:
        cost, u, used = heapq.heappop(heap)
        if u == dst:
            return cost
        if used > k or fewest.get(u, float('inf')) <= used:
            continue                   # a cheaper pop already arrived with fewer edges
        fewest[u] = used
        for v, w in graph[u]:
            heapq.heappush(heap, (cost + w, v, used + 1))
    return -1

