def network_delay_time(times, n, k):
    INF = float('inf')
    dist = [INF] * (n + 1)
    dist[k] = 0
    for _ in range(n - 1):             # n − 1 rounds of relaxing every edge
        for u, v, w in times:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    worst = max(dist[1:])
    return -1 if worst == INF else worst

